// Ownership is binding — do not edit this file if it is not yours. docs/OWNERSHIP.tsv
// Appointments: list mine, book (self, or minors when Head), cancel. Styles: styles/appointments.css.
import { type FormEvent, useCallback, useEffect, useMemo, useState } from 'react'

import { useSearchParams } from 'react-router-dom'
import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { useAppSelector } from '../../store/hooks'
import {
  apiClient,
  doctorWorkspaceApi,
  threePortalApi,
  type AppointmentDto,
  type DoctorSlotsDto,
  type DoctorSummaryDto,
  type FamilyDto,
  type MemberDto,
} from '../../services/apiClient'
import { FriendlyStatusBadge } from './threePortalShared'
import { extractErrorMessage, formatDateTime } from './threePortalUtils'
import { todayLocalDate } from '../records/recordSummaryMeta'

type ApptTab = 'upcoming' | 'requests' | 'past'
type SortOrder = 'soonest' | 'latest'

function isMinor(member: MemberDto): boolean {
  const dob = new Date(member.dateOfBirth)
  if (Number.isNaN(dob.getTime())) return false
  const cutoff = new Date()
  cutoff.setUTCFullYear(cutoff.getUTCFullYear() - 18)
  return dob > cutoff
}

function memberOptionLabel(member: MemberDto): string {
  if (member.role === 'Head') return `${member.displayName} (Family Head)`
  if (member.role === 'MinorMember') return `${member.displayName} (Minor)`
  return member.displayName
}

/** Mutually exclusive buckets: every appointment lands in exactly one tab. */
function appointmentTab(appointment: AppointmentDto, now: number = Date.now()): ApptTab {
  const future = new Date(appointment.startsAt).getTime() >= now
  if (future && appointment.status === 'Confirmed') return 'upcoming'
  if (future && appointment.status === 'Requested') return 'requests'
  return 'past'
}

function initials(name: string): string {
  const parts = name.replace(/^dr\.?\s+/i, '').split(/\s+/).filter(Boolean)
  return (parts.slice(0, 2).map((part) => part[0]).join('') || '?').toUpperCase()
}

const colomboTime = (iso: string) =>
  new Date(iso).toLocaleTimeString('en-US', { timeZone: 'Asia/Colombo', hour: 'numeric', minute: '2-digit' })

const TABS: { id: ApptTab; label: string }[] = [
  { id: 'upcoming', label: 'Upcoming' },
  { id: 'requests', label: 'Requests' },
  { id: 'past', label: 'Past' },
]

export function AppointmentsPage() {
  const user = useAppSelector((state) => state.auth.user)
  const isHead = user?.role === 'FAMILY_HEAD'

  const [appointments, setAppointments] = useState<AppointmentDto[]>([])
  const [members, setMembers] = useState<MemberDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [tab, setTab] = useState<ApptTab>('upcoming')
  const [memberFilter, setMemberFilter] = useState('all')
  const [sortOrder, setSortOrder] = useState<SortOrder>('soonest')
  const [expandedId, setExpandedId] = useState<string | null>(null)

  // Server marks the caller's own member row with isSelf; it still rejects (404) booking for anyone else.
  const bookableMembers = useMemo(
    () => members.filter((member) => member.isSelf || (isHead && isMinor(member))),
    [members, isHead],
  )

  const [familyId, setFamilyId] = useState('')
  const [familyDoctor, setFamilyDoctor] = useState<DoctorSummaryDto | null>(null)
  const [searchParams] = useSearchParams()
  const initialDate = /^\d{4}-\d{2}-\d{2}$/.test(searchParams.get('date') ?? '') ? searchParams.get('date')! : ''
  const initialSlot = searchParams.get('slot') ?? ''
  const [selectedDate, setSelectedDate] = useState(initialDate)
  const [selectedSlot, setSelectedSlot] = useState('')
  const [attachmentName, setAttachmentName] = useState('')
  const [slots, setSlots] = useState<DoctorSlotsDto | null>(null)
  const [slotMessage, setSlotMessage] = useState('')
  // One request lifecycle for deep links and manual date changes; old dates cannot replace current slots.
  useEffect(() => {
    if (!familyId || !selectedDate) return
    let active = true
    setSlots(null)
    setSelectedSlot('')
    setSlotMessage('')
    void doctorWorkspaceApi.getFamilyDoctorSlots(familyId, selectedDate).then(({ data }) => {
      if (!active) return
      setSlots(data)
      setSelectedSlot(data.slots.includes(initialSlot) ? initialSlot : '')
    }).catch(() => { if (active) setSlotMessage('Free times could not be loaded. Choose another date or enter a time to request it.') })
    return () => { active = false }
  }, [familyId, selectedDate, initialSlot])

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const [{ data: appts }, { data: family }] = await Promise.all([
        threePortalApi.getMyAppointments(),
        apiClient.get<FamilyDto>('/families/me'),
      ])
      setAppointments(appts)
      setMembers(family.members)
      setFamilyId(family.id)

      // Bookings always go to the family's assigned doctor (the server decides), so this is display only.
      try {
        const { data: doctor } = await apiClient.get<DoctorSummaryDto | null>(`/families/${family.id}/doctor`)
        setFamilyDoctor(doctor?.id ? doctor : null)
      } catch {
        setFamilyDoctor(null)
      }

      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  const counts = useMemo(() => {
    const result: Record<ApptTab, number> = { upcoming: 0, requests: 0, past: 0 }
    const now = Date.now()
    for (const appointment of appointments) result[appointmentTab(appointment, now)] += 1
    return result
  }, [appointments])
  const completedCount = appointments.filter((appointment) => appointment.status === 'Completed').length

  const memberChoices = useMemo(() => {
    const seen = new Map<string, string>()
    for (const appointment of appointments) seen.set(appointment.memberId, appointment.memberDisplayName)
    return [...seen.entries()]
  }, [appointments])

  const visible = useMemo(() => {
    const now = Date.now()
    const direction = sortOrder === 'soonest' ? 1 : -1
    return appointments
      .filter((appointment) => appointmentTab(appointment, now) === tab)
      .filter((appointment) => memberFilter === 'all' || appointment.memberId === memberFilter)
      .sort((a, b) => direction * (new Date(a.startsAt).getTime() - new Date(b.startsAt).getTime()))
  }, [appointments, tab, memberFilter, sortOrder])

  async function book(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const formElement = event.currentTarget
    const form = new FormData(formElement)
    const memberId = String(form.get('memberId') || '')
    const date = String(form.get('date') || '')
    const time = String(form.get('time') || '')
    const slot = slots?.availabilityConfigured ? selectedSlot : ''
    const reason = String(form.get('reason') || '').trim()
    const attachment = (formElement.elements.namedItem('attachment') as HTMLInputElement | null)?.files?.[0]
    if (!memberId || !date || !(time || slot) || !reason) {
      setMessage('Please fill in all appointment details.')
      return
    }

    if (slot && (!slots?.slots.includes(slot) || slots.date !== date)) { setMessage('Available times changed. Choose the appointment date and time again.'); return }
    const startsAt = slot || new Date(`${date}T${time}:00+05:30`).toISOString()
    setSubmitting(true)
    setMessage('')
    try {
      await threePortalApi.bookAppointment({
        memberId,
        startsAt,
        reason,
        durationMinutes: slots?.availabilityConfigured ? slots.slotMinutes : 30,
      })
      // Upload only after the booking exists, and say so plainly if the file did not go through.
      let attachmentNote = ''
      if (attachment instanceof File && attachment.size > 0) {
        const uploadForm = new FormData()
        uploadForm.append('file', attachment)
        uploadForm.append('collectedAt', new Date().toISOString())
        try {
          await apiClient.post(`/members/${memberId}/lab-reports`, uploadForm, {
            headers: { 'Content-Type': 'multipart/form-data' },
          })
          attachmentNote = ` "${attachment.name}" was saved to the member's lab reports.`
        } catch {
          attachmentNote = ` "${attachment.name}" could not be uploaded — add it from Health records (PNG, JPEG or PDF, up to 10 MB).`
        }
      }
      formElement.reset()
      setAttachmentName('')
      setSelectedDate('')
      setSelectedSlot('')
      setSlots(null)
      setMessage(`Appointment requested. You will be notified once the doctor confirms it.${attachmentNote}`)
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Appointment could not be booked.'))
    } finally {
      setSubmitting(false)
    }
  }

  async function cancel(appointment: AppointmentDto) {
    if (!window.confirm('Cancel this appointment?')) return
    try {
      await threePortalApi.cancelAppointment(appointment.id)
      setMessage('Appointment cancelled.')
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Appointment could not be cancelled.'))
    }
  }

  if (status === 'loading') return <LoadingState label="Loading appointments" />
  if (status === 'error') return <ErrorState message="Appointments could not be loaded." onRetry={() => void load()} />

  const stats = [
    { key: 'upcoming', label: 'Upcoming', value: String(counts.upcoming), hint: 'Confirmed visits ahead' },
    { key: 'awaiting', label: 'Awaiting doctor', value: String(counts.requests), hint: 'Requests not yet accepted' },
    { key: 'completed', label: 'Completed', value: String(completedCount), hint: 'Visits already held' },
    { key: 'doctor', label: 'Family doctor', value: familyDoctor?.displayName ?? 'Not assigned', hint: familyDoctor?.specialty ?? 'Choose one under My Doctor' },
  ]

  return (
    <div className="page-stack appt">
      <header className="appt-hero">
        <div className="appt-hero__text">
          <p className="appt-hero__eyebrow">Appointments</p>
          <h1>Appointments</h1>
          <p>Request a visit with your family doctor and keep track of every booking in one place.</p>
        </div>
        <aside className="appt-hero__note" aria-label="Privacy">
          <strong>Privacy</strong>
          <p>{isHead
            ? "Appointments for you and your minors. Adults' private appointments are not shown here."
            : 'Your own appointments. They are private from the Family Head.'}</p>
        </aside>
      </header>

      {message && <p role="status" className="status-banner">{message}</p>}

      <ul className="appt-stats" aria-label="Appointment summary">
        {stats.map((stat) => (
          <li key={stat.key} className={`appt-stat appt-stat--${stat.key}`}>
            <span className="appt-stat__label">{stat.label}</span>
            <strong className="appt-stat__value">{stat.value}</strong>
            <small>{stat.hint}</small>
          </li>
        ))}
      </ul>

      <div className="appt-grid">
        <section className="appt-card appt-book" aria-labelledby="appt-book-title">
          <h2 id="appt-book-title">Book an appointment</h2>
          <form className="appt-form" onSubmit={(event) => void book(event)}>
            <label className="appt-field">
              <span>Member</span>
              <select name="memberId" required defaultValue="">
                <option value="" disabled>Select member</option>
                {bookableMembers.map((member) => (
                  <option key={member.id} value={member.id}>
                    {memberOptionLabel(member)}
                  </option>
                ))}
              </select>
            </label>

            <div className="appt-field">
              <span>Doctor</span>
              {familyDoctor ? (
                <div className="appt-doctor">
                  <span className="appt-avatar" aria-hidden="true">{initials(familyDoctor.displayName)}</span>
                  <div>
                    <strong>{familyDoctor.displayName}</strong>
                    {familyDoctor.specialty && <small>{familyDoctor.specialty}</small>}
                    <small>Your family doctor. Appointments are booked with them.</small>
                  </div>
                </div>
              ) : (
                <p className="appt-doctor appt-doctor--empty">No family doctor is assigned yet. Choose one under My Doctor before booking.</p>
              )}
            </div>

            <label className="appt-field">
              <span>Date</span>
              <input
                name="date"
                type="date"
                required
                min={todayLocalDate()}
                value={selectedDate}
                onChange={(event) => {
                  setSelectedDate(event.target.value)
                  setSlots(null)
                  setSelectedSlot('')
                  setSlotMessage('')
                }}
              />
            </label>

            {slots?.availabilityConfigured ? (
              <div className="appt-field" role="group" aria-labelledby="appt-slot-label">
                <span id="appt-slot-label">Free time</span>
                {slots.slots.length === 0 ? <span className="appt-muted">No free times on this day. Try another date.</span> : (
                  <>
                    <div className="appt-slots">
                      {slots.slots.map((slot) => (
                        <button
                          key={slot}
                          type="button"
                          className="appt-slot"
                          aria-pressed={selectedSlot === slot}
                          onClick={() => setSelectedSlot(slot)}
                        >
                          {colomboTime(slot)}
                        </button>
                      ))}
                    </div>
                    <small className="appt-muted">{slots.slotMinutes}-minute appointments · Sri Lanka time</small>
                  </>
                )}
              </div>
            ) : (
              <label className="appt-field">
                <span>Time</span>
                <input name="time" type="time" required />
                {slots && <small className="appt-muted">Your doctor has not set weekly hours yet, so request any time and they will confirm it.</small>}
              </label>
            )}
            {slotMessage && <p className="appt-muted">{slotMessage}</p>}

            <label className="appt-field">
              <span>Reason</span>
              <textarea name="reason" required maxLength={200} rows={3} placeholder="e.g. Follow-up consultation" />
            </label>

            <div className="appt-field">
              <span>Attachment (optional)</span>
              <input
                type="file"
                name="attachment"
                id="appointment-attachment"
                accept=".pdf,image/png,image/jpeg"
                className="sr-only"
                onChange={(e) => {
                  const f = e.target.files?.[0]
                  setAttachmentName(f ? f.name : '')
                }}
              />
              <label htmlFor="appointment-attachment" className="appt-drop">
                <span className="appt-drop__title">{attachmentName ? 'Change report' : 'Upload medical report / referral'}</span>
                <small>{attachmentName || 'PDF, PNG or JPEG, up to 10 MB. Saved to lab reports after booking.'}</small>
              </label>
            </div>

            <button className="button button--primary appt-submit" type="submit" disabled={submitting}>
              {submitting ? 'Booking…' : 'Book appointment'}
            </button>
            <p className="appt-info">A request is not confirmed until your doctor accepts it. You will be notified.</p>
          </form>
        </section>

        <section className="appt-card appt-list" aria-labelledby="appt-list-title">
          <div className="appt-list__head">
            <h2 id="appt-list-title">My appointments</h2>
            <div className="appt-tools">
              <label className="appt-tool">
                <span className="sr-only">Filter by member</span>
                <select value={memberFilter} onChange={(event) => setMemberFilter(event.target.value)}>
                  <option value="all">All members</option>
                  {memberChoices.map(([id, name]) => <option key={id} value={id}>{name}</option>)}
                </select>
              </label>
              <label className="appt-tool">
                <span className="sr-only">Sort appointments</span>
                <select value={sortOrder} onChange={(event) => setSortOrder(event.target.value as SortOrder)}>
                  <option value="soonest">Earliest first</option>
                  <option value="latest">Latest first</option>
                </select>
              </label>
            </div>
          </div>

          <div className="appt-tabs" role="tablist" aria-label="Appointment groups">
            {TABS.map((item) => (
              <button
                key={item.id}
                type="button"
                role="tab"
                id={`appt-tab-${item.id}`}
                aria-selected={tab === item.id}
                aria-controls="appt-tabpanel"
                className="appt-tab"
                onClick={() => { setTab(item.id); setExpandedId(null) }}
              >
                {item.label} <span className="appt-tab__count">{counts[item.id]}</span>
              </button>
            ))}
          </div>

          <div id="appt-tabpanel" role="tabpanel" aria-labelledby={`appt-tab-${tab}`}>
            {visible.length === 0 ? (
              <EmptyState
                title={appointments.length === 0 ? 'No appointments yet' : 'Nothing here'}
                message={appointments.length === 0 ? 'Book an appointment to get started.' : 'No appointments match this view.'}
              />
            ) : (
              <ul className="appt-items">
                {visible.map((appointment) => {
                  const start = new Date(appointment.startsAt)
                  const open = expandedId === appointment.id
                  return (
                    <li key={appointment.id} className={`appt-item appt-item--${appointment.status.toLowerCase()}`}>
                      <div className="appt-item__row">
                        <div className="appt-datebox" aria-hidden="true">
                          <strong>{start.getDate()}</strong>
                          <small>{start.toLocaleDateString(undefined, { month: 'short' })}</small>
                          <small>{start.toLocaleDateString(undefined, { weekday: 'short' })}</small>
                        </div>
                        <div className="appt-item__body">
                          <strong>{appointment.memberDisplayName}</strong>
                          <span>{appointment.doctor?.displayName ?? '—'}</span>
                          <small>{formatDateTime(appointment.startsAt)} · {appointment.durationMinutes} min</small>
                        </div>
                        <div className="appt-item__side">
                          <FriendlyStatusBadge status={appointment.status} />
                          <div className="appt-item__actions">
                            <button
                              type="button"
                              className="button button--secondary"
                              aria-expanded={open}
                              aria-controls={`appt-detail-${appointment.id}`}
                              onClick={() => setExpandedId(open ? null : appointment.id)}
                            >
                              {open ? 'Hide' : 'View'}
                            </button>
                            {(appointment.status === 'Requested' || appointment.status === 'Confirmed') && (
                              <button className="button button--danger" type="button" onClick={() => void cancel(appointment)}>
                                Cancel
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                      {open && (
                        <dl className="appt-detail" id={`appt-detail-${appointment.id}`}>
                          <div><dt>Reason</dt><dd>{appointment.reason || '—'}</dd></div>
                          <div><dt>Duration</dt><dd>{appointment.durationMinutes} minutes</dd></div>
                          <div><dt>Doctor's note</dt><dd>{appointment.doctorNote || 'No note yet'}</dd></div>
                          <div><dt>Requested</dt><dd>{formatDateTime(appointment.createdAt)}</dd></div>
                        </dl>
                      )}
                    </li>
                  )
                })}
              </ul>
            )}
          </div>
        </section>
      </div>
    </div>
  )
}
